26|            const msg = String(this.state.error);
27|            const stack = this.state.info?.componentStack;
28|            return (
29|                <div style={{
30|                    minHeight: '100vh',
31|                    background: '#0b0c14',
32|                    color: '#f0ede8',
33|                    display: 'flex',
34|                    alignItems: 'center',
35|                    justifyContent: 'center',
36|                    fontFamily: 'monospace',
37|                    padding: 40,
38|                }}>
39|                    <div style={{ maxWidth: 800, width: '100%' }}>
40|                        <div style={{ color: '#ff4f5e', fontSize: 18, fontWeight: 900, marginBottom: 16 }}>
41|                            ⚡ LifeOS1 — Runtime Error
42|                        </div>
43|                        <div style={{
44|                            background: '#13141f',
45|                            borderRadius: 8,
46|                            padding: 20,
47|                            marginBottom: 16,
48|                            border: '1px solid rgba(255,79,94,0.3)',
49|                        }}>
50|                            <div style={{ color: '#ff8c42', fontWeight: 700, marginBottom: 8 }}>{msg}</div>
