52|                                color: '#6aaedd',
53|                                fontSize: 11,
54|                                whiteSpace: 'pre-wrap',
55|                                overflow: 'auto',
56|                                maxHeight: 400
57|                            }}>
58|                                {stack || 'No stack trace available'}
59|                            </div>
60|                        </div>
61|                        <button
62|                            onClick={() => {
63|                                this.setState({ error: null, info: null });
64|                                window.location.reload();
65|                            }}
66|                            style={{
67|                                background: '#9b72cf',
68|                                border: 'none',
69|                                color: '#fff',
