71|                                borderRadius: 6,
72|                                cursor: 'pointer',
73|                                fontWeight: 700,
74|                                transition: 'all 0.18s ease',
75|                            }}
76|                            onMouseEnter={e => { e.currentTarget.style.background = '#8b62bf'; }}
77|                            onMouseLeave={e => { e.currentTarget.style.background = '#9b72cf'; }}
