92|// ── Single mount — ErrorBoundary wraps everything ──
93|const root = createRoot(document.getElementById('root'));
94|
95|async function start() {
96|    console.info('[LifeOS1] build', import.meta.env.VITE_LIFEOS_BUILD_ID || 'dev');
97|
98|    try {
99|        await Promise.race([
100|            hydrateFromCloud(),
101|            new Promise((r) => setTimeout(r, 1500)),
102|        ]);
103|    } catch (e) {
104|        console.error('[persistBridge] hydrate error:', e);
105|    }
